function renderLayers(){const d=editor.doc,out=[];function walk(parent=null,depth=0){for(const l of d.layers.filter(l=>l.parent===parent).reverse()){out.push(`<div class="layer ${editor.selected.includes(l.id)?'selected':''}" data-layer="${l.id}" draggable="true" style="padding-left:${6+depth*12}px"><button class="layer-eye" data-visible="${l.id}" aria-label="${l.visible?'레이어 숨기기':'레이어 표시'}">${ico(l.visible?'eye':'eye-off')}</button>${l.type==='group'?`<button class="thumb thumbicon" data-collapse="${l.id}" title="그룹 접기 / 펼치기">${ico(collapsed.has(l.id)?'folder':'folder-open')}</button>`:l.type==='adjustment'?`<div class="thumb thumbicon">${ico('sliders-horizontal')}</div>`:`<canvas class="thumb" data-thumb="${l.id}"></canvas>`}<div class="layerinfo"><div class="layername">${esc(l.name)}</div><div class="layertype">${typeName(l)}${l.clipping?' · 클리핑':''}${l.filters?.length?' · 스마트 필터':''}</div></div>${l.mask?`<button class="layerbadge" data-mask-edit="${l.id}" title="마스크 편집">${ico(l.editMask?'square-dashed':'square')}</button>`:''}${l.locked?`<span class="layerbadge">${ico('lock')}</span>`:l.filters?.length?'<span class="layerbadge">fx</span>':''}</div>`);if(l.type==='group'&&!collapsed.has(l.id))walk(l.id,depth+1)}}walk();$('#layers').innerHTML=out.join('');for(const c of $$('[data-thumb]')){const l=d.layers.find(l=>l.id===c.dataset.thumb);c.width=c.height=40;const src=editor.source(l),x=c.getContext('2d'),scale=Math.min(40/src.width,40/src.height);x.drawImage(src,(40-src.width*scale)/2,(40-src.height*scale)/2,src.width*scale,src.height*scale)}}
let historyPanel='history';function renderHistory(){if(historyPanel==='navigator'){const h=$('#history');h.innerHTML='<canvas id="navcanvas" style="width:100%;height:83px"></canvas>';if(rendered){const c=$('#navcanvas');c.width=250;c.height=83;const s=Math.min(250/rendered.width,83/rendered.height);c.getContext('2d').drawImage(rendered,(250-rendered.width*s)/2,0,rendered.width*s,rendered.height*s)}return}$('#history').innerHTML=editor.history.map((h,i)=>`<button data-history="${i}" class="${editor.index===i?'current':''}" style="${i>editor.index?'opacity:.4':''}">${ico(i===0?'file-image':'history')} ${esc(h.label)}</button>`).join('');const el=$('[data-history="'+editor.index+'"]');el?.scrollIntoView({block:'nearest'})}
