function positionCanvas(){const d=editor.doc,s=$('#shell');s.style.width=d.width+'px';s.style.height=d.height+'px';s.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;$('#tabzoom').textContent=`${Math.round(zoom*100)}%`;$('#zoomLabel').textContent=`${Math.round(zoom*100)}%`;$('#statusZoom').textContent=`${Math.round(zoom*100)}%`;drawOverlay()}
