function exportDialog(){const d=editor.doc;modal('이미지 내보내기',`<p>표시 중인 레이어·마스크·보정·효과를 합성합니다.</p><label>형식<select name="format"><option value="png">PNG · 투명도 지원</option><option value="jpeg">JPEG · 흰색 배경</option><option value="webp">WebP · 투명도 지원</option></select></label><div class="sliderrow"><span>품질</span><input type="range" name="quality" min="1" max="100" value="92"><span id="qualityLabel">92%</span></div><label>크기<select name="scale"><option value="1">원본 · ${d.width} × ${d.height}</option><option value="0.5">50%</option><option value="2">200%</option></select></label>`,'내보내기',async f=>{closeModal();await busy('이미지 내보내는 중…',async()=>{const format=f.get('format'),scale=+f.get('scale');if(d.width*d.height*scale*scale>100000000)throw new Error('내보내기 크기는 최대 100 메가픽셀입니다.');const src=await editor.render(),c=canvas(d.width*scale,d.height*scale),x=c.getContext('2d');if(format==='jpeg'){x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height)}x.drawImage(src,0,0,c.width,c.height);const blob=await new Promise(res=>c.toBlob(res,'image/'+format,+f.get('quality')/100));if(!blob)throw new Error('이 브라우저에서 내보내기를 완료할 수 없습니다.');download(blob,d.name+'.'+(format==='jpeg'?'jpg':format));toast('이미지 내보내기가 완료되었습니다.')})});$('[name="quality"]').oninput=e=>$('#qualityLabel').textContent=e.target.value+'%'}
let database;async function db(){if(database)return database;database=await new Promise((res,rej)=>{const r=indexedDB.open('atelier-studio',1);r.onupgradeneeded=()=>r.result.createObjectStore('projects');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});return database}
async function dbGet(){const b=await db();return new Promise((res,rej)=>{const r=b.transaction('projects').objectStore('projects').get('autosave');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}
