async function importFiles(files,place=false){for(let i=0;i<files.length;i++){const f=files[i],n=f.name||'붙여넣은 이미지';await busy(n+' 여는 중…',async()=>{if(/\.psd$/i.test(n)){const buffer=await f.arrayBuffer();const original=new Uint8Array(buffer.slice(0));const report=await editor.importPSD(buffer,n.replace(/\.psd$/i,''));editor.doc.psdOriginal=original;editor.history[editor.index].doc.psdOriginal=original;selection=null;fit();modal('PSD 가져오기 결과',`<div class="report">${esc(report.join('\n\n'))}</div>`,null)}else if(/\.(atelier|json)$/i.test(n)){const p=JSON.parse(await f.text());if(p.doc?.psdOriginal&&!ArrayBuffer.isView(p.doc.psdOriginal))p.doc.psdOriginal=new Uint8Array(Object.values(p.doc.psdOriginal));await editor.load(p);selection=null;fit()}else await importImage(f,n,place||i>0)})}}
